import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures availability before frame 0
const { fontFamily: interFamily } = loadInter();



export type InutiliReelProps = Record<string, any>;

const InutiliReel: React.FC<InutiliReelProps> = ({
  backgroundColor = "#E6D6CE",
  transparentBackground = false,
  durationInSeconds = 5,
  text1 = "rughe",
  text2 = "macchie",
  text3 = "filler",
  text4 = "soluzioni invasive",
  pillColor = "#ad49a3",
  textColor = "#FFFFFF",
  lineColor = "#ad49a3",
  fontSize = 72,
  floatAmplitude = 15,
  floatSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Canvas scale factor to ensure responsive sizing across 9:16 or 16:9
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const durationInFrames = durationInSeconds * fps;

  // Dissolve starts at 65% of duration
  const dissolveStartFrame = Math.round(durationInFrames * 0.65);

  // Timings for the drawing dashed line
  const lineStartFrame = Math.round(fps * 0.2);
  const lineEndFrame = Math.round(dissolveStartFrame - fps * 0.3);
  const lineDuration = Math.max(1, lineEndFrame - lineStartFrame);

  // Line Draw Progress
  const lineDrawProgress = interpolate(
    frame,
    [lineStartFrame, lineEndFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Trigger frames for each word based on when the path passes them
  const word1TriggerFrame = lineStartFrame + lineDuration * 0.15;
  const word2TriggerFrame = lineStartFrame + lineDuration * 0.40;
  const word3TriggerFrame = lineStartFrame + lineDuration * 0.65;
  const word4TriggerFrame = lineStartFrame + lineDuration * 0.90;

  // Entrance Springs
  const word1Spring = spring({
    frame: frame - word1TriggerFrame,
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 100 },
  });
  const word2Spring = spring({
    frame: frame - word2TriggerFrame,
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 100 },
  });
  const word3Spring = spring({
    frame: frame - word3TriggerFrame,
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 100 },
  });
  const word4Spring = spring({
    frame: frame - word4TriggerFrame,
    fps,
    config: { damping: 12, mass: 0.8, stiffness: 100 },
  });

  // Entrance Scales and Opacities
  const scale1 = frame >= word1TriggerFrame ? interpolate(word1Spring, [0, 1], [0, 1]) : 0;
  const opacity1 = frame >= word1TriggerFrame ? interpolate(word1Spring, [0, 1], [0, 1]) : 0;

  const scale2 = frame >= word2TriggerFrame ? interpolate(word2Spring, [0, 1], [0, 1]) : 0;
  const opacity2 = frame >= word2TriggerFrame ? interpolate(word2Spring, [0, 1], [0, 1]) : 0;

  const scale3 = frame >= word3TriggerFrame ? interpolate(word3Spring, [0, 1], [0, 1]) : 0;
  const opacity3 = frame >= word3TriggerFrame ? interpolate(word3Spring, [0, 1], [0, 1]) : 0;

  const scale4 = frame >= word4TriggerFrame ? interpolate(word4Spring, [0, 1], [0, 1]) : 0;
  const opacity4 = frame >= word4TriggerFrame ? interpolate(word4Spring, [0, 1], [0, 1]) : 0;

  // Dissolve (Dematerialization) Stagger Timings
  const dissolveDuration = Math.round(fps * 0.8);
  const dStart1 = dissolveStartFrame;
  const dStart2 = dissolveStartFrame + Math.round(fps * 0.12);
  const dStart3 = dissolveStartFrame + Math.round(fps * 0.24);
  const dStart4 = dissolveStartFrame + Math.round(fps * 0.36);

  const dissolveProgress1 = interpolate(
    frame,
    [dStart1, dStart1 + dissolveDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const dissolveProgress2 = interpolate(
    frame,
    [dStart2, dStart2 + dissolveDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const dissolveProgress3 = interpolate(
    frame,
    [dStart3, dStart3 + dissolveDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const dissolveProgress4 = interpolate(
    frame,
    [dStart4, dStart4 + dissolveDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Main Pill appearance combined with dissolve transition (quick fade out as particles release)
  const pillOpacity1 = opacity1 * interpolate(dissolveProgress1, [0, 0.4], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pillScale1 = scale1 * interpolate(dissolveProgress1, [0, 0.4], [1, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const pillOpacity2 = opacity2 * interpolate(dissolveProgress2, [0, 0.4], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pillScale2 = scale2 * interpolate(dissolveProgress2, [0, 0.4], [1, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const pillOpacity3 = opacity3 * interpolate(dissolveProgress3, [0, 0.4], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pillScale3 = scale3 * interpolate(dissolveProgress3, [0, 0.4], [1, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const pillOpacity4 = opacity4 * interpolate(dissolveProgress4, [0, 0.4], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pillScale4 = scale4 * interpolate(dissolveProgress4, [0, 0.4], [1, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Dashed Line fades out when dissolution starts
  const lineOpacity = interpolate(
    frame,
    [dissolveStartFrame, dissolveStartFrame + Math.round(fps * 0.4)],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Individual float phases
  const floatPhase = (frame / fps) * floatSpeed * Math.PI * 2;
  const floatY1 = Math.sin(floatPhase) * (floatAmplitude * s);
  const floatY2 = Math.sin(floatPhase + 2.0) * (floatAmplitude * s);
  const floatY3 = Math.sin(floatPhase + 4.0) * (floatAmplitude * s);
  const floatY4 = Math.sin(floatPhase + 6.0) * (floatAmplitude * s);

  // Position 4 words beautifully
  const word1Pos = { x: width * 0.35, y: height * 0.26 };
  const word2Pos = { x: width * 0.65, y: height * 0.38 };
  const word3Pos = { x: width * 0.32, y: height * 0.52 };
  const word4Pos = { x: width * 0.62, y: height * 0.66 };

  // Curved line weaving perfectly through the 4 words
  const pathD = `M ${width * 0.5} ${height * 0.1} Q ${width * 0.1} ${height * 0.18}, ${word1Pos.x} ${word1Pos.y} T ${word2Pos.x} ${word2Pos.y} T ${word3Pos.x} ${word3Pos.y} T ${word4Pos.x} ${word4Pos.y} T ${width * 0.5} ${height * 0.82}`;
  const pathLength = height * 1.8;

  const padY = 32 * s;
  const padX = 64 * s;

  // Particle System Parameters
  const numParticles = 35;
  const particleIndices = Array.from({ length: numParticles }, (_, i) => i);

  // Render particle dispersion outward to borders
  const renderParticles = (
    wordIndex: number,
    wordPos: { x: number; y: number },
    progress: number
  ) => {
    if (progress <= 0 || progress >= 1) return null;

    return particleIndices.map((i) => {
      const seed = (str: string) => random(`${wordIndex}-${i}-${str}`);
      const angle = seed("angle") * Math.PI * 2;
      
      // Target distances reaching beyond screen boundaries (from 0.6x to 1.4x of width)
      const maxDistance = (width * 0.6) + seed("dist") * (width * 0.8);
      
      // Accelerating burst ease curve
      const travelProgress = 1 - Math.pow(1 - progress, 2.5);
      
      // Floating wave turbulence
      const waveAmplitude = seed("wave-amp") * 100 * s;
      const waveFreq = 1 + seed("wave-freq") * 4;
      const wave = Math.sin(progress * Math.PI * waveFreq) * waveAmplitude;
      
      const perpX = -Math.sin(angle);
      const perpY = Math.cos(angle);
      
      const posX = wordPos.x + Math.cos(angle) * (maxDistance * travelProgress) + perpX * wave;
      const posY = wordPos.y + Math.sin(angle) * (maxDistance * travelProgress) + perpY * wave;
      
      const initialSize = (4 + seed("size") * 12) * s;
      const currentSize = initialSize * (1 - progress);
      
      const op = interpolate(progress, [0, 0.05, 0.6, 1], [0, 1, 1, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      });
      
      const isPillColor = seed("color-choice") > 0.45;
      const color = isPillColor ? pillColor : textColor;
      
      const isRound = seed("shape") > 0.35;
      const borderRadius = isRound ? "50%" : `${currentSize / 2}px`;
      const aspect = isRound ? 1 : 1.5 + seed("aspect") * 1.5;
      const widthVal = currentSize * aspect;
      const heightVal = currentSize;
      
      const rotation = angle * (180 / Math.PI) + (progress * seed("spin") * 360);

      return (
        <div
          key={`part-${wordIndex}-${i}`}
          style={{
            position: "absolute",
            left: posX,
            top: posY,
            width: widthVal,
            height: heightVal,
            backgroundColor: color,
            borderRadius,
            opacity: op,
            transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
            pointerEvents: "none",
            zIndex: 4,
          }}
        />
      );
    });
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Dashed Line Animation */}
      <svg
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          top: 0,
          left: 0,
          pointerEvents: "none",
          opacity: lineOpacity,
          zIndex: 2,
        }}
      >
        <defs>
          <mask id="line-mask">
            <path
              d={pathD}
              fill="none"
              stroke="white"
              strokeWidth={30 * s}
              strokeLinecap="round"
              strokeDasharray={pathLength}
              strokeDashoffset={pathLength * (1 - lineDrawProgress)}
            />
          </mask>
        </defs>

        <path
          d={pathD}
          fill="none"
          stroke={lineColor}
          strokeWidth={6 * s}
          strokeLinecap="round"
          strokeDasharray={`${15 * s}, ${15 * s}`}
          mask="url(#line-mask)"
        />
      </svg>

      {/* Word 1 */}
      <div
        style={{
          position: "absolute",
          left: word1Pos.x,
          top: word1Pos.y,
          transform: `translate(-50%, -50%) scale(${pillScale1}) translateY(${floatY1}px)`,
          opacity: pillOpacity1,
          backgroundColor: pillColor,
          borderRadius: 9999 * s,
          padding: `${padY}px ${padX}px`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
          willChange: "transform, opacity",
          zIndex: 3,
        }}
      >
        <span
          style={{
            color: textColor,
            fontFamily: interFamily,
            fontWeight: 900,
            fontSize: `${fontSize * s}px`,
            letterSpacing: "-0.05em",
            lineHeight: 1,
            paddingBottom: `${4 * s}px`,
            whiteSpace: "nowrap",
          }}
        >
          {text1}
        </span>
      </div>

      {/* Word 2 */}
      <div
        style={{
          position: "absolute",
          left: word2Pos.x,
          top: word2Pos.y,
          transform: `translate(-50%, -50%) scale(${pillScale2}) translateY(${floatY2}px)`,
          opacity: pillOpacity2,
          backgroundColor: pillColor,
          borderRadius: 9999 * s,
          padding: `${padY}px ${padX}px`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
          willChange: "transform, opacity",
          zIndex: 3,
        }}
      >
        <span
          style={{
            color: textColor,
            fontFamily: interFamily,
            fontWeight: 900,
            fontSize: `${fontSize * s}px`,
            letterSpacing: "-0.05em",
            lineHeight: 1,
            paddingBottom: `${4 * s}px`,
            whiteSpace: "nowrap",
          }}
        >
          {text2}
        </span>
      </div>

      {/* Word 3 */}
      <div
        style={{
          position: "absolute",
          left: word3Pos.x,
          top: word3Pos.y,
          transform: `translate(-50%, -50%) scale(${pillScale3}) translateY(${floatY3}px)`,
          opacity: pillOpacity3,
          backgroundColor: pillColor,
          borderRadius: 9999 * s,
          padding: `${padY}px ${padX}px`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
          willChange: "transform, opacity",
          zIndex: 3,
        }}
      >
        <span
          style={{
            color: textColor,
            fontFamily: interFamily,
            fontWeight: 900,
            fontSize: `${fontSize * s}px`,
            letterSpacing: "-0.05em",
            lineHeight: 1,
            paddingBottom: `${4 * s}px`,
            whiteSpace: "nowrap",
          }}
        >
          {text3}
        </span>
      </div>

      {/* Word 4 */}
      <div
        style={{
          position: "absolute",
          left: word4Pos.x,
          top: word4Pos.y,
          transform: `translate(-50%, -50%) scale(${pillScale4}) translateY(${floatY4}px)`,
          opacity: pillOpacity4,
          backgroundColor: pillColor,
          borderRadius: 9999 * s,
          padding: `${padY}px ${padX}px`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
          willChange: "transform, opacity",
          zIndex: 3,
        }}
      >
        <span
          style={{
            color: textColor,
            fontFamily: interFamily,
            fontWeight: 900,
            fontSize: `${fontSize * s}px`,
            letterSpacing: "-0.05em",
            lineHeight: 1,
            paddingBottom: `${4 * s}px`,
            whiteSpace: "nowrap",
          }}
        >
          {text4}
        </span>
      </div>

      {/* Dematerialization Particle Systems */}
      {renderParticles(1, { x: word1Pos.x, y: word1Pos.y + floatY1 }, dissolveProgress1)}
      {renderParticles(2, { x: word2Pos.x, y: word2Pos.y + floatY2 }, dissolveProgress2)}
      {renderParticles(3, { x: word3Pos.x, y: word3Pos.y + floatY3 }, dissolveProgress3)}
      {renderParticles(4, { x: word4Pos.x, y: word4Pos.y + floatY4 }, dissolveProgress4)}
    </AbsoluteFill>
  );
};

export default InutiliReel;